// WF-1 Normalize Lead — decide this lead's identity once, before anything is spent on it.
//
// lead_id rule (fixed — every later workflow recomputes it to find this row again):
//   the Apollo person id when the lead has one, otherwise the first 16 hex chars of
//   sha256(lowercased, trimmed email). Deterministic, collision-free at pilot scale, and it needs
//   no lookup against the Sheet.

// ---- sha256, inline ----------------------------------------------------------------------
// Implemented here rather than via require('crypto') because n8n's Code sandbox only exposes
// node builtins when NODE_FUNCTION_ALLOW_BUILTIN is set on the host. lead_id is the key every
// later workflow updates this row against, so it must not depend on a host env flag.
function sha256hex(msg) {
  const K = [
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  let H = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const rr = (v, n) => ((v >>> n) | (v << (32 - n))) >>> 0;
  const bytes = [];
  for (let i = 0; i < msg.length; i++) {
    let c = msg.charCodeAt(i);
    if (c < 0x80) bytes.push(c);
    else if (c < 0x800) bytes.push(0xc0 | (c >> 6), 0x80 | (c & 63));
    else if (c < 0xd800 || c >= 0xe000) bytes.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    else {
      i++;
      const cp = 0x10000 + (((c & 0x3ff) << 10) | (msg.charCodeAt(i) & 0x3ff));
      bytes.push(0xf0 | (cp >> 18), 0x80 | ((cp >> 12) & 63), 0x80 | ((cp >> 6) & 63), 0x80 | (cp & 63));
    }
  }
  const bitLen = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  const hi = Math.floor(bitLen / 0x100000000), lo = bitLen >>> 0;
  bytes.push((hi >>> 24) & 255, (hi >>> 16) & 255, (hi >>> 8) & 255, hi & 255,
             (lo >>> 24) & 255, (lo >>> 16) & 255, (lo >>> 8) & 255, lo & 255);
  const w = new Array(64);
  for (let off = 0; off < bytes.length; off += 64) {
    for (let i = 0; i < 16; i++) {
      w[i] = ((bytes[off + i * 4] << 24) | (bytes[off + i * 4 + 1] << 16) |
              (bytes[off + i * 4 + 2] << 8) | bytes[off + i * 4 + 3]) >>> 0;
    }
    for (let i = 16; i < 64; i++) {
      const s0 = (rr(w[i-15], 7) ^ rr(w[i-15], 18) ^ (w[i-15] >>> 3)) >>> 0;
      const s1 = (rr(w[i-2], 17) ^ rr(w[i-2], 19) ^ (w[i-2] >>> 10)) >>> 0;
      w[i] = (w[i-16] + s0 + w[i-7] + s1) >>> 0;
    }
    let a = H[0], b = H[1], c = H[2], d = H[3], e = H[4], f = H[5], g = H[6], h = H[7];
    for (let i = 0; i < 64; i++) {
      const S1 = (rr(e, 6) ^ rr(e, 11) ^ rr(e, 25)) >>> 0;
      const ch = ((e & f) ^ (~e & g)) >>> 0;
      const t1 = (h + S1 + ch + K[i] + w[i]) >>> 0;
      const S0 = (rr(a, 2) ^ rr(a, 13) ^ rr(a, 22)) >>> 0;
      const maj = ((a & b) ^ (a & c) ^ (b & c)) >>> 0;
      const t2 = (S0 + maj) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    H = [(H[0]+a)>>>0,(H[1]+b)>>>0,(H[2]+c)>>>0,(H[3]+d)>>>0,
         (H[4]+e)>>>0,(H[5]+f)>>>0,(H[6]+g)>>>0,(H[7]+h)>>>0];
  }
  return H.map(x => x.toString(16).padStart(8, '0')).join('');
}

// ---- identifier normalisation (must stay identical in every node that compares identifiers) ----
function normEmail(v) { return String(v == null ? '' : v).trim().toLowerCase(); }
function normDomain(v) {
  return String(v == null ? '' : v).trim().toLowerCase()
    .replace(/^https?:\/\//, '').replace(/^www\./, '')
    .replace(/[/?#].*$/, '');
}
function normLinkedIn(v) {
  let s = String(v == null ? '' : v).trim().toLowerCase();
  if (!s) return '';
  s = s.replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/[?#].*$/, '').replace(/\/+$/, '');
  return s;
}
function normPhone(v) {
  // Compare on the last 10 digits so +1-202-555-0143, 12025550143 and (202) 555-0143 all match.
  // Lossy for some international numbers, but it errs toward MORE suppression matches, which is
  // the only safe direction for a compliance check.
  const d = String(v == null ? '' : v).replace(/\D/g, '');
  return d.length > 10 ? d.slice(-10) : d;
}
function emailDomain(email) {
  const e = normEmail(email);
  return e.indexOf('@') > -1 ? normDomain(e.split('@').pop()) : '';
}

return $input.all().map(item => {
  const l = item.json || {};
  const email = normEmail(l.email || l.contact_email);
  const apollo_id = String(l.apollo_id == null ? '' : l.apollo_id).trim();
  const lead_id = apollo_id || (email ? sha256hex(email).slice(0, 16) : '');
  const company_domain = normDomain(l.company_domain);
  const linkedin_url = normLinkedIn(l.linkedin_url);
  const phone = normPhone(l.phone);

  return { json: {
    lead_id: lead_id,
    lead_id_source: apollo_id ? 'apollo_id' : (email ? 'sha256(email)' : 'none'),
    source_config: String(l.source_config || ''),
    apollo_id: apollo_id,
    first_name: String(l.first_name || ''),
    last_name: String(l.last_name || ''),
    title: String(l.title || ''),
    company: String(l.company || ''),
    company_domain: company_domain,
    email: email,
    contact_email: email,
    phone: String(l.phone || ''),
    linkedin_url: String(l.linkedin_url || ''),
    timezone: String(l.timezone || ''),
    signal: String(l.signal || ''),
    has_email: email ? true : false,
    has_phone: phone ? true : false,
    // normalised comparison keys — the gate and nothing else reads these
    _ids: {
      email: email,
      email_domain: emailDomain(email),
      company_domain: company_domain,
      linkedin: linkedin_url,
      phone: phone
    }
  }};
});

// WF-1 Gate — the two checks that must happen BEFORE a Reoon credit is spent.
//
//   1. Suppression (compliance-critical): drop the lead if ANY identifier it has matches ANY row
//      on the Suppression tab. A lead suppressed under one channel must never resurface under
//      another, so email / email-domain / company-domain / phone / linkedin are all checked, and a
//      row with a blank or unrecognised identifier_type is compared against every identifier shape
//      rather than ignored. Erring toward blocking is the only safe direction here.
//   2. Dedupe: skip a lead already on the Leads tab (matched on contact_email, and on lead_id so an
//      Apollo id we already hold under a different address is still caught). Re-verifying a lead we
//      already hold buys nothing and costs a credit.
//
// Suppression is evaluated first so a lead that is both suppressed and a duplicate is reported as
// suppressed — that is the answer that matters in an audit.
//
// Fail-closed: a lead with neither an Apollo id nor an email has no stable key and cannot be
// deduped or suppression-checked reliably, so it is skipped rather than verified.

// ---- identifier normalisation (must stay identical in every node that compares identifiers) ----
function normEmail(v) { return String(v == null ? '' : v).trim().toLowerCase(); }
function normDomain(v) {
  return String(v == null ? '' : v).trim().toLowerCase()
    .replace(/^https?:\/\//, '').replace(/^www\./, '')
    .replace(/[/?#].*$/, '');
}
function normLinkedIn(v) {
  let s = String(v == null ? '' : v).trim().toLowerCase();
  if (!s) return '';
  s = s.replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/[?#].*$/, '').replace(/\/+$/, '');
  return s;
}
function normPhone(v) {
  // Compare on the last 10 digits so +1-202-555-0143, 12025550143 and (202) 555-0143 all match.
  // Lossy for some international numbers, but it errs toward MORE suppression matches, which is
  // the only safe direction for a compliance check.
  const d = String(v == null ? '' : v).replace(/\D/g, '');
  return d.length > 10 ? d.slice(-10) : d;
}
function emailDomain(email) {
  const e = normEmail(email);
  return e.indexOf('@') > -1 ? normDomain(e.split('@').pop()) : '';
}

const leadItems = $('Normalize Lead').all();

// A Sheets read on a tab holding only its header row returns no rows; alwaysOutputData then hands
// us a single empty placeholder item. Drop those so "empty tab" never looks like a real row.
const real = (arr) => arr.map(i => i.json || {}).filter(r => Object.keys(r).length > 0);
const leadRows = real($('Read Leads (dedupe)').all());
const suppRows = real($('Read Suppression').all());

// ---- suppression index ----
const supp = { email: new Set(), phone: new Set(), linkedin: new Set(), domain: new Set(), untyped: new Set() };
const add = (set, v) => { if (v) set.add(v); };
for (const r of suppRows) {
  const t = String(r.identifier_type || '').trim().toLowerCase();
  const raw = String(r.identifier_value || '').trim();
  if (!raw) continue;
  if (t === 'email') add(supp.email, normEmail(raw));
  else if (t === 'phone') add(supp.phone, normPhone(raw));
  else if (t === 'linkedin') add(supp.linkedin, normLinkedIn(raw));
  else if (t === 'domain') add(supp.domain, normDomain(raw));
  else {
    add(supp.untyped, normEmail(raw));
    add(supp.untyped, normPhone(raw));
    add(supp.untyped, normLinkedIn(raw));
    add(supp.untyped, normDomain(raw));
  }
}

// ---- existing-lead index ----
const seenEmail = new Set(), seenId = new Set();
for (const r of leadRows) {
  const e = normEmail(r.contact_email);
  if (e) seenEmail.add(e);
  const id = String(r.lead_id || '').trim();
  if (id) seenId.add(id);
}

return leadItems.map(item => {
  const lead = item.json || {};
  const ids = lead._ids || {};
  let gate_action = 'verify', gate_reason = 'ok', gate_detail = '';

  const checks = [
    ['email', ids.email, supp.email],
    ['domain_from_email', ids.email_domain, supp.domain],
    ['company_domain', ids.company_domain, supp.domain],
    ['phone', ids.phone, supp.phone],
    ['linkedin', ids.linkedin, supp.linkedin]
  ];
  const hits = [];
  for (const [label, value, set] of checks) {
    if (value && set.has(value)) hits.push(label + '=' + value);
  }
  for (const [label, value] of Object.entries(ids)) {
    if (value && supp.untyped.has(value)) hits.push('untyped:' + label + '=' + value);
  }

  if (!lead.lead_id) {
    gate_action = 'skip';
    gate_reason = 'no_identifier';
    gate_detail = 'lead has neither an apollo_id nor an email - no stable key, refusing to verify';
  } else if (hits.length) {
    gate_action = 'skip';
    gate_reason = 'suppressed';
    gate_detail = 'suppression match on ' + hits.join(', ');
  } else if (seenEmail.has(ids.email) || seenId.has(lead.lead_id)) {
    gate_action = 'skip';
    gate_reason = 'duplicate';
    gate_detail = 'already on the Leads tab (' +
      (seenEmail.has(ids.email) ? 'contact_email=' + ids.email : 'lead_id=' + lead.lead_id) +
      ') - not re-verifying';
  }

  return { json: Object.assign({}, lead, {
    gate_action: gate_action,
    gate_reason: gate_reason,
    gate_detail: gate_detail,
    leads_rows_scanned: leadRows.length,
    suppression_rows_scanned: suppRows.length,
    gated_at: new Date().toISOString()
  })};
});

// WF-1 Classify — map Reoon power-mode result to an action.
// Gate on `status`, per the live-tested Reoon behaviour in INTEGRATIONS.md:
//   safe/valid           -> pass
//   invalid/spamtrap     -> drop (SMTP-confirmed bad)
//   disposable           -> needs_review  (Reoon mis-flags greylisted corporate domains as
//                                          disposable - a false negative; a human confirms)
//   catch_all/unknown/role/anything else -> needs_review
// DO NOT "improve" this mapping. Auto-dropping on `disposable` silently loses good leads.
//
// The lead is recovered by email (Reoon echoes the address it verified) rather than by item index,
// because the gate's IF node removes skipped leads and indices no longer line up.
const gated = $('Gate (dedupe + suppression)').all();
const byEmail = {};
for (const g of gated) {
  const e = String((g.json || {}).email || '').toLowerCase();
  if (e) byEmail[e] = g.json;
}
let verified = [];
try { verified = $('Verify this lead?').all(0); } catch (e) { verified = []; }

return $input.all().map((item, i) => {
  const r = item.json || {};
  const lead = byEmail[String(r.email || '').toLowerCase()] ||
               ((verified[i] || {}).json) || {};
  const status = String(r.status || 'unknown').toLowerCase();
  const score = (r.overall_score !== undefined ? r.overall_score : null);
  let action, reason;
  if (['safe', 'valid'].includes(status)) {
    action = 'pass'; reason = 'deliverable, safe to send';
  } else if (['invalid', 'spamtrap'].includes(status)) {
    action = 'drop'; reason = 'hard fail: ' + status;
  } else if (status === 'disposable') {
    action = 'needs_review';
    reason = 'flagged disposable - confirm real throwaway vs greylisted corporate (known Reoon false-negative)';
  } else {
    action = 'needs_review'; reason = 'ambiguous (' + status + ') - human judges';
  }
  return { json: {
    lead_id: lead.lead_id || null,
    email: lead.email || r.email || null,
    name: [lead.first_name, lead.last_name].filter(Boolean).join(' ') || null,
    company: lead.company || null,
    reoon_status: status,
    overall_score: score,
    is_safe_to_send: (r.is_safe_to_send !== undefined ? r.is_safe_to_send : null),
    is_catch_all: (r.is_catch_all !== undefined ? r.is_catch_all : null),
    is_deliverable: (r.is_deliverable !== undefined ? r.is_deliverable : null),
    action: action,
    reason: reason,
    verified_at: new Date().toISOString(),
    lead: lead
  }};
});

// Shape the Events row for the Reoon call that just happened. Keys MUST equal Events column names.
//
// est_cost_usd is deliberately left blank: COSTS.md records Reoon's $/credit as [UNKNOWN] on
// purpose ("measure, don't estimate"), and a made-up number in the cost meter is worse than a gap.
// `units: 1` is the honest, meterable fact - one /verify call, one credit.
return $input.all().map(item => {
  const c = item.json || {};
  const l = c.lead || {};
  const detail = [c.reoon_status, (c.overall_score === null || c.overall_score === undefined)
    ? null : 'score ' + c.overall_score].filter(Boolean).join(', ');
  return { json: {
    timestamp: c.verified_at || new Date().toISOString(),
    lead_id: c.lead_id || '',
    lead_email: c.email || '',
    tool: 'reoon',
    action: 'verify',
    units: 1,
    est_cost_usd: '',
    result: c.action + (detail ? ' (' + detail + ')' : ''),
    workflow: 'VIO-intake-verify-curate',
    source_config: l.source_config || ''
  }};
});

// Shape the Leads row. Keys here MUST equal Leads column names exactly — the Sheets node runs in
// autoMapInputData mode and matches on the header text, so a typo silently drops a value.
// (`handlingExtraData: ignoreIt` on that node stops an unexpected key from adding a new column.)
//
// Columns this stage genuinely cannot know yet are written as empty strings rather than left out,
// so the row is full-width and later in-place updates line up.
return $input.all().map(item => {
  const c = item.json || {};
  const l = c.lead || {};
  const now = new Date().toISOString();
  return { json: {
    lead_id: c.lead_id || '',
    source_config: l.source_config || '',
    apollo_id: l.apollo_id || '',
    first_name: l.first_name || '',
    last_name: l.last_name || '',
    title: l.title || '',
    company: l.company || '',
    company_domain: l.company_domain || '',
    has_email: l.has_email === true,
    has_phone: l.has_phone === true,
    contact_email: c.email || '',
    phone: l.phone || '',
    linkedin_url: l.linkedin_url || '',
    timezone: l.timezone || '',
    signal: l.signal || '',
    opener: '',
    email_draft: '',
    reoon_status: c.reoon_status || '',
    verify_action: c.action || '',
    verify_reason: c.reason || '',
    sendr_page_id: '',
    sendr_page_url: '',
    gif_url: '',
    channel_state_email: 'not_sent',
    channel_state_linkedin: 'not_sent',
    idempotency_key: '',
    reply_received: false,
    reply_sentiment: '',
    reply_out_of_office: false,
    // 4-value enum, never a boolean: not_eligible / pending_approval / called / skipped.
    // `pending_approval` is the legally-required human gate before any automated call (TCPA), so a
    // new lead starts at not_eligible and only a confirmed positive reply can ever move it.
    call_state: 'not_eligible',
    meeting_booked: false,
    created_at: now,
    updated_at: now
  }};
});
